import Testing
import Foundation

@Suite("Misc Lint Tests")
struct MiscLintTests {

    @Test func noStaticOverFinalClassViolations() throws {
        try assertZeroViolations(for: "static_over_final_class")
    }

    @Test func noSetenvViolations() throws {
        try assertZeroViolations(for: "no_setenv")
    }

    @Test func noGeometryReaderInListViolations() throws {
        try assertZeroViolations(for: "no_geometry_reader_in_list")
    }

    @Test func noCyclomaticComplexityViolations() throws {
        try assertZeroViolations(for: "cyclomatic_complexity")
    }

    @Test func noForWhereViolations() throws {
        try assertZeroViolations(for: "for_where")
    }

    private func assertZeroViolations(for rule: String) throws {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        // we'll run shell script because grep is easier
        process.arguments = ["bash", "-c", "swiftlint lint --quiet | grep -c \(rule) || true"]

        let pipe = Pipe()
        process.standardOutput = pipe

        try process.run()
        process.waitUntilExit()

        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        let output = String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "0"
        let count = Int(output) ?? 0

        #expect(count == 0, "Found \(count) violations for \(rule)")
    }
}

