import Domain
import SwiftUI

public extension EnvironmentValues {
    @Entry var textScale: CGFloat = 1.0
}

// MARK: - Broadsheet Root View

@MainActor
public struct BroadsheetRootView: View {
    @State private var appState: BroadsheetAppState
    @State private var currentsVM = CurrentsViewModel()
    @AppStorage("textSizeStep") private var textSizeStep = 0
    @AppStorage("hasCompletedOnboarding") private var hasCompletedOnboarding = false

    private let permissionService: any PermissionService

    private var textScale: CGFloat {
        pow(1.12, CGFloat(textSizeStep))
    }

    public init(appState: BroadsheetAppState, permissionService: any PermissionService) {
        _appState = State(initialValue: appState)
        self.permissionService = permissionService
    }

    public var body: some View {
        VStack(spacing: 0) {
            MastheadView(
                waveformVM: appState.waveformVM,
                isRecording: appState.isRecording
            )

            NavigationSplitView(columnVisibility: .constant(.all)) {
                BroadsheetSidebarView()
                    .navigationSplitViewColumnWidth(min: 180, ideal: Metrics.sidebar, max: 320)
                    .background(SquareCorners())
            } content: {
                BroadsheetMeetingListView()
                    .navigationSplitViewColumnWidth(min: 260, ideal: Metrics.listColumn, max: 480)
                    .background(SquareCorners())
            } detail: {
                VStack(spacing: 0) {
                    let selected = appState.selectedDisplayMeeting
                    BroadsheetDetailHeader(meeting: selected)
                    RecordingDeck()
                    BroadsheetDetailTabs()
                    BroadsheetDockBar()
                }
                .background(Color.bg)
            }

            // Full-width headline ticker — spans all three columns
            CurrentsView(headlines: currentsVM.headlines)
        }
        .background(Color.bg)
        .toolbarBackground(Color.bg, for: .windowToolbar)
        .overlay(alignment: .top) {
            if let toast = appState.toast {
                ToastView(message: toast, onDismiss: { appState.dismissToast() })
                    .padding(.top, 8)
                    .transition(.move(edge: .top).combined(with: .opacity))
            }
        }
        .animation(.easeInOut(duration: 0.25), value: appState.toast)
        .sheet(isPresented: Binding(
            get: { !hasCompletedOnboarding },
            set: { if !$0 { hasCompletedOnboarding = true } }
        )) {
            OnboardingView(permissionService: permissionService) { hasCompletedOnboarding = true }
        }
        .environment(appState)
        .environment(\.textScale, textScale)
        .task {
            if let liveVM = appState.liveTranscriptionVM {
                await currentsVM.observe(liveVM)
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: .recordingStarted)) { _ in
            Task { await appState.handleRecordingStarted() }
        }
        .onReceive(NotificationCenter.default.publisher(for: .recordingStopped)) { _ in
            Task { await appState.handleRecordingStopped() }
        }
        // #181: keyboard shortcuts extracted to a named @ViewBuilder property so SwiftUI
        // assigns stable view identities across body passes instead of recreating 4 Buttons
        // inside an anonymous Group{} closure every render.
        .background(keyboardShortcuts)
    }

    // MARK: - Text Size Keyboard Shortcuts (#181)

    /// ⌘+ / ⌘= / ⌘- / ⌘0 keyboard shortcuts for text size.
    /// Extracted from the body's .background(Group{}) lambda so SwiftUI can assign
    /// a stable identity to these Buttons across body evaluations.
    @ViewBuilder
    private var keyboardShortcuts: some View {
        Button("") { textSizeStep = min(textSizeStep + 1, 6) }
