import AppKit
import Domain
import SwiftUI

@MainActor
public struct MenuBarPopover: View {
    @State var viewModel: MenuBarViewModel
    let permissionService: any PermissionService
    /// Drives the first-launch onboarding sheet. False when `hasCompletedOnboarding` is already set.
    @State private var showOnboarding: Bool

    public init(viewModel: MenuBarViewModel, permissionService: any PermissionService = NoOpPermissionService()) {
        _viewModel = State(initialValue: viewModel)
        self.permissionService = permissionService
        let hasCompletedOnboarding = UserDefaults.standard.bool(forKey: "hasCompletedOnboarding")
        _showOnboarding = State(initialValue: !hasCompletedOnboarding)
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(viewModel.statusMessage).font(.headline)
            recordingButton
            retranscribeButton
            UpcomingMeetingsListView(
                sections: viewModel.upcomingMeetingSectionsCached,
                isLoading: viewModel.isLoadingUpcomingMeetings,
                reload: { Task { await viewModel.loadUpcomingMeetings() } }
            )
            transcriptionSection
            statusSection
            Divider()
            footerBar
        }
        .frame(width: 320)
        .padding()
        .task {
            await viewModel.loadUpcomingMeetings()
            await viewModel.runStartupCleanup()
        }
        .sheet(isPresented: $showOnboarding) {
            OnboardingView(permissionService: permissionService) {
                UserDefaults.standard.set(true, forKey: "hasCompletedOnboarding")
                showOnboarding = false
            }
        }
    }
}

import Domain
import SwiftUI

// MARK: - Delete All Data section (#123)

// Bridge: call site uses SettingsView.deleteAllDataSection; inject NoOpDataEraser until
// the composition root wires a real DataEraser.
extension SettingsView {
    var deleteAllDataSection: some View {
        DeleteAllDataSection(viewModel: viewModel, dataEraser: NoOpDataEraser())
    }
}

// MARK: - DeleteAllDataSection

struct DeleteAllDataSection: View {
    @Bindable var viewModel: SettingsViewModel
    let dataEraser: any DataEraser

    @State private var showDeleteAllConfirmation = false
    @State private var deleteError: String? = nil
    @State private var deletionTask: Task<Void, Never>? = nil

    var body: some View {
        Section("Data Management") {
            VStack(alignment: .leading, spacing: 8) {
                Text(
                    "Permanently erase all recordings, transcripts, ML cache, Keychain entries, " +
                        "and app preferences. This cannot be undone."
                )
                .font(.caption)
                .foregroundStyle(.secondary)

                TextField(
                    "Type DELETE to confirm",
                    text: $viewModel.deleteAllConfirmationText
                )
                .textFieldStyle(.roundedBorder)
                .disableAutocorrection(true)

                HStack {
                    Spacer()
                    Button("Delete All Data") {
                        showDeleteAllConfirmation = true
                    }
                    .buttonStyle(.borderedProminent)
                    .tint(.red)
                    .disabled(!viewModel.isDeleteAllConfirmed || !viewModel.isDeleteAllDataEnabled)
                    Spacer()
                }
                .padding(.top, 4)

                if viewModel.isDeletingAllData {
                    ProgressView("Deleting…")
                        .progressViewStyle(.linear)
                }

                if !viewModel.deleteAllDataLog.isEmpty {
                    Text("Deleted: " + viewModel.deleteAllDataLog.joined(separator: ", "))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
            }
            .confirmationDialog(
                "Delete All Data",
                isPresented: $showDeleteAllConfirmation,
                titleVisibility: .visible
            ) {
                Button("Delete Everything", role: .destructive) {
                    deletionTask?.cancel()
                    deletionTask = Task {
                        do {
                            try await viewModel.performDeleteAllData(dataEraser: dataEraser)
                        } catch is CancellationError {
                            return
                        } catch {
                            deleteError = error.localizedDescription
                        }
                    }
                }
                Button("Cancel", role: .cancel) {
                    viewModel.deleteAllConfirmationText = ""
                }
            } message: {
                Text(
                    "This cannot be undone. All recordings, transcripts, credentials, " +
                        "and settings will be permanently erased."
                )
            }
            .alert(
                "Deletion Failed",
                isPresented: Binding(
                    get: { deleteError != nil },
                    set: { if !$0 { deleteError = nil } }
                )
            ) {
                Button("OK") { deleteError = nil }
            } message: {
                Text(deleteError ?? "")
            }
        }
        .onDisappear { deletionTask?.cancel() }
    }
}

// MARK: - NoOpDataEraser (placeholder for composition-root injection)

private enum NoOpDataEraserError: Error {
    case notWired
}

/// Placeholder eraser: always throws so the error alert fires.
/// The production composition root replaces this with a fully-wired `LiveDataEraser`.
struct NoOpDataEraser: DataEraser {
    func eraseAllData() async throws -> [String] {
        throw NoOpDataEraserError.notWired
    }
}

